	/** 
	 * jumpstart the process by instantiating2 Review
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		reviewId = ReviewService.getReviewInstance()
		.createReview( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		ReviewService.getReviewInstance()
				.createReview( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.reviewSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Review : " + successValue.getReviewId());
							  if (successValue.getReviewId().equals(reviewId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfReviewList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Review test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on review consumed")
					);
			subscriber.reviewSubscribe( reviewId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Review : " + successValue.getReviewId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfReviewList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on review for reviewId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Review. 
	 */
	protected Review read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Review" );

		Review entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Review with primary key" );
		msg.append( reviewId );
		
		ReviewFetchOneSummary fetchOneSummary = new ReviewFetchOneSummary( reviewId );

		try {
			entity = ReviewService.getReviewInstance().getReview( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Review " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Review.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Review." );

		StringBuilder msg = new StringBuilder( "Failed to update a Review : " );        
		Review entity = read();
		UpdateReviewCommand command = generateUpdateCommand();
		command.setReviewId(entity.getReviewId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Review." );

			// for use later on...
			reviewId = entity.getReviewId();

			ReviewService proxy = ReviewService.getReviewInstance();  

			proxy.updateReview( command ).get();

			LOGGER.info( "-- Successfully saved Review - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + reviewId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Review.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Review." );

		Review entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Review with id " + reviewId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Review with id " + reviewId );

			throw e;
		}

		try{
			ReviewService.getReviewInstance().delete( new DeleteReviewCommand( entity.getReviewId() ) ).get();
			LOGGER.info( "-- Successfully deleted Review with id " + reviewId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Review with id " + reviewId );

			throw e;
		}
	}

	/**
	 * get all Reviews.
	 */
	protected List<Review> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Reviews:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Review : " );        
		List<Review> collection  = new ArrayList<>();

		try {
			// call the static get method on the ReviewService
			collection = ReviewService.getReviewInstance().getAllReview();
			assertNotNull( collection, "An Empty collection of Review was incorrectly returned.");
			
			// Now print out the values
			Review entity = null;            
			Iterator<Review> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getReviewId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

